\label{teo 1.2}
Let  $N\geq 1$, $B_R(0)$ be the ball centered at the origin and $\lambda^{\ln,\mu}_{1}$
denote the first Dirichlet eigenvalue of ${\mathcal L}_\mu$.

$(i)$ If $\mu\in(-1,0]$, then for any bounded Lipschitz domain $\Omega\subset\mathbb{R}^N$
with $0\in\Omega$ and $|\Omega|=|B_R(0)|$,
\begin{equation}\label{eq:FK-small}
  \lambda_1^{\ln,\mu}(\Omega)
  \;\geq\;
  \lambda_1^{\ln,\mu}(B_R(0)).
\end{equation}
Equality holds if and only if $\Omega=B_R(0)$.


$(ii)$ If $\mu>0$, then there exists a bounded Lipschitz domain $\Omega$ such that $0\in\Omega$,
$|\Omega|=|B_R(0)|$ and
\begin{equation}\label{eq:FK-fail}
  \lambda_1^{\ln,\mu}(\Omega)
  \;<\;
  \lambda_1^{\ln,\mu}(B_R(0)).
\end{equation}

\cite[Proposition 1.1]{LWY}\label{lem:domain-hardy}
Let  $  \Omega\subset \mathbb{R}^N$ be a  bounded Lipschitz domain with $N\geq 1$ containing the origin.
For every $u\in C_c^\infty(\Omega)$, then 
\begin{equation}\label{eq 01}
2\int_\Omega\big(\log\frac1{|x|}\big)\,u(x)^2\,dx+ d_{N,\Omega}   \|u\|_{2}^2\leq \|u\|_{\ln}^2\,,
\end{equation}
where
$$d_{N,\Omega}= 2\psi\!\big(\frac N4 \big)-2\psi\!\big(\frac N2 \big) +1-\gamma-C_N |\Omega|^{\frac12},\qquad \ C_N=c_N(\int_{\mathbb{R}^N\setminus B_1(0)} |y|^{-2N}dy)^{\frac12}\, .$$

\cite[Theorem 1.2]{LWY}
	\label{prop:energy-space}
	  Let  $  \Omega\subset \mathbb{R}^N$ be a  bounded Lipschitz domain with $N\geq 1$ containing the origin.
Then
		\begin{equation}\label{eq:space-identification}
			{\mathbb H}_0^{\ln,\mu}(\Omega)\cong {\mathbb H}_0^{\ln}(\Omega)\qquad {\rm for}\ \ \mu>-1,
			\end{equation}
	and the embedding
		\begin{equation}\label{eq:perturbed-compact}
			\mathbb H_0^{\ln,\mu}(\Omega)\hookrightarrow L^2(\Omega)
		\end{equation}
		is continuous for $\mu\geq -1$
		and compact for $\mu>-1$ and non-compact for $\mu=-1$.

\label{lm 2.2}
Assume that \(N\ge 1\), \(w:[0,\infty)\to\mathbb R\) is strictly increasing
 and \(f:[0,\infty)\to[0,\infty)\) is strictly increasing, locally Lipschitz continuous. 
 Let \(u\) be a nonnegative function such that \(u\in L^1(\mathbb{R}^N,w\,dx)\), then 
\begin{equation}\label{inq 2.1}
 \int_{\mathbb R^N} w(|x|)\, f(u^\#(x))\,dx
   \;\le\;
  \int_{\mathbb R^N} w(|x|)\, f(u(x))\,dx,
\end{equation}
furthermore, the equality holds if and only if
\[
  u^\#=u \qquad \text{a.e. in } \mathbb R^N.
\]
